import 'dart:io';
String scope(String s){final ip=InternetAddress.tryParse(s);if(ip==null)return'invalid';if(ip.isLoopback||ip.isLinkLocal||s.startsWith('10.')||s.startsWith('192.168.')||s.startsWith('172.16.')||s.startsWith('172.17.')||s.startsWith('172.18.')||s.startsWith('172.19.'))return'local/intranet';return'public';}
Future<void> main()async{final p=int.tryParse(Platform.environment['NETWORK_API_PORT']??'8787')??8787;print({'schema':'bizx.network.api.v1','implementation':'dart','port':p,'endpoints':['catalog','health','config','interfaces','classify','authorize','tcp-check']});print('scope 127.0.0.1 = ${scope('127.0.0.1')}');try{final s=await Socket.connect('127.0.0.1',p,timeout:const Duration(seconds:1));s.destroy();print('local API port reachable');}catch(_){print('local API port not reachable (normal if server not running)');}}
